#!/usr/bin/env python3
"""
Flood Relief Multimodal Routing - PySCIPOpt solver.
Reads public data from /app/data/, solves MILP, writes /app/submissions/solution.csv.
"""

import os
import sys
import csv
import json
import itertools
import time
from pathlib import Path

# Ensure we can import pyscipopt
try:
    from pyscipopt import Model, quicksum, SCIP
except ImportError:
    print("ERROR: pyscipopt not available")
    sys.exit(1)

DATA_DIR = Path("/app/data")
SUB_DIR = Path("/app/submissions")
SUB_DIR.mkdir(parents=True, exist_ok=True)

# ---------------------------------------------------------------------------
# Load data
# ---------------------------------------------------------------------------
def load_config():
    with open(DATA_DIR / "config.json") as f:
        return json.load(f)

def load_csv(name):
    with open(DATA_DIR / name) as f:
        return list(csv.DictReader(f))

config = load_config()
staging_rows = load_csv("staging_points.csv")
road_rows = load_csv("road_edges.csv")
shelter_rows = load_csv("shelters.csv")
drone_rows = load_csv("drone_options.csv")
boat_rows = load_csv("boat_travel.csv")
priority_rows = load_csv("priority_weights.csv")
weather_rows = load_csv("weather_windows.csv")

DEPOT = config["depot_id"]
TRUCK_SVC_PER_KG = config["truck_service_minutes_per_kg"]
DRONE_SETUP = config["drone_setup_minutes"]
BOAT_SETUP = config["boat_setup_minutes"]
BOAT_UNLOAD_PER = config["boat_unload_minutes_per_shelter"]
TRUCK_FIXED = config["truck_fixed_stop_minutes"]
DRONE_CAP = config["drone_capacity_kg"]
DRONE_ENDURANCE = config["drone_endurance_minutes"]
BOAT_CAP = config["boat_capacity_kg"]
BOAT_TRIP_LIMIT = config["boat_trip_limit_minutes"]
LATE_PEN = config["late_penalty_per_weighted_minute"]
RISK_PEN = config["risk_penalty_minutes_per_point"]

# Staging points
staging = {}
for r in staging_rows:
    nid = r["node_id"]
    staging[nid] = {
        "name": r["node_name"],
        "x": float(r["x_km"]),
        "y": float(r["y_km"]),
        "clearance": r["launch_clearance"],
        "ramp": int(r["boat_ramp"]),
        "handling": float(r["handling_minutes"]),
        "zone": r["field_zone"],
    }

nodes = list(staging.keys())
node_idx = {n: i for i, n in enumerate(nodes)}
n_nodes = len(nodes)

# Road edges (undirected, take min if duplicate)
road_time = {}
for r in road_rows:
    u, v = r["from_node"], r["to_node"]
    t = float(r["travel_minutes"])
    if (u, v) not in road_time or t < road_time[(u, v)]:
        road_time[(u, v)] = t
    if (v, u) not in road_time or t < road_time[(v, u)]:
        road_time[(v, u)] = t

# Shelters
shelters = {}
for r in shelter_rows:
    hid = r["shelter_id"]
    shelters[hid] = {
        "name": r["shelter_name"],
        "area": r["area_type"],
        "dry_node": r["nearest_dry_node"] if r["nearest_dry_node"] else None,
        "demand": float(r["demand_kg"]),
        "priority": r["priority"],
        "deadline": float(r["deadline_minutes"]),
    }

shelter_ids = list(shelters.keys())
n_shelters = len(shelter_ids)

# Priority weights
pweights = {r["priority"]: float(r["weight"]) for r in priority_rows}

# Weather: max multipliers (conservative for feasibility)
max_drone_mult = max(float(r["drone_multiplier"]) for r in weather_rows)
max_boat_mult = max(float(r["boat_multiplier"]) for r in weather_rows)

# Drone options (filtered)
drone_opts = []  # (shelter, launch, flight, risk)
for r in drone_rows:
    hid = r["shelter_id"]
    ln = r["launch_node"]
    if int(r["payload_feasible"]) != 1:
        continue
    if staging[ln]["clearance"] == "poor":
        continue
    flight = float(r["flight_minutes"])
    risk = float(r["landing_risk"])
    # Endurance check with worst-case weather
    total = DRONE_SETUP + flight * max_drone_mult + RISK_PEN * risk
    if total > DRONE_ENDURANCE + 1e-9:
        continue
    drone_opts.append((hid, ln, flight, risk))

drone_opt_set = set((h, s) for (h, s, f, rk) in drone_opts)
drone_flight = {(h, s): f for (h, s, f, rk) in drone_opts}
drone_risk = {(h, s): rk for (h, s, f, rk) in drone_opts}

# Boat travel times
boat_time = {}
for r in boat_rows:
    u, v = r["from_id"], r["to_id"]
    t = float(r["minutes"])
    boat_time[(u, v)] = t
    # Also allow reverse? The data seems directed. Keep as directed.

# ---------------------------------------------------------------------------
# Enumerate feasible boat trips per ramp
# A boat trip: (ramp, ordered list of flooded shelters)
# Constraints: total demand <= BOAT_CAP, total duration (travel + unload) * max_boat_mult <= BOAT_TRIP_LIMIT
# ---------------------------------------------------------------------------
flooded_ids = [h for h in shelter_ids if shelters[h]["area"] == "flooded"]
ramp_nodes = [n for n in nodes if staging[n]["ramp"] == 1]

def boat_trip_duration(ramp, order):
    """Compute base duration (no weather multiplier) for a boat trip."""
    dur = BOAT_SETUP
    # Travel from ramp to first
    if order:
        if (ramp, order[0]) not in boat_time:
            return None
        dur += boat_time[(ramp, order[0])]
        for i in range(len(order) - 1):
            a, b = order[i], order[i + 1]
            if (a, b) not in boat_time:
                return None
            dur += boat_time[(a, b)]
        # Return to ramp
        if (order[-1], ramp) not in boat_time:
            return None
        dur += boat_time[(order[-1], ramp)]
    # Unload time
    dur += BOAT_UNLOAD_PER * len(order)
    return dur

def boat_trip_demand(order):
    return sum(shelters[h]["demand"] for h in order)

# Enumerate all feasible boat trips (up to size 4 to keep manageable)
boat_trips = []  # list of (ramp, tuple(order), duration_base)
for ramp in ramp_nodes:
    # Get flooded shelters reachable from this ramp
    reachable = [h for h in flooded_ids if (ramp, h) in boat_time]
    max_size = 4  # limit enumeration size
    for size in range(1, max_size + 1):
        for combo in itertools.combinations(reachable, size):
            for perm in itertools.permutations(combo):
                if boat_trip_demand(list(perm)) > BOAT_CAP + 1e-9:
                    continue
                dur = boat_trip_duration(ramp, list(perm))
                if dur is None:
                    continue
                if dur * max_boat_mult > BOAT_TRIP_LIMIT + 1e-9:
                    continue
                boat_trips.append((ramp, perm, dur))

# Deduplicate: for same (ramp, frozenset(order)), keep min duration? No, order matters for duration.
# Actually each (ramp, perm) is distinct. But we may have many. Let's cap.
# Filter: only keep trips that are "useful" - i.e., not dominated by another trip at same ramp serving same set with <= duration.
from collections import defaultdict
trip_by_set = defaultdict(list)
for (ramp, perm, dur) in boat_trips:
    key = (ramp, frozenset(perm))
    trip_by_set[key].append((perm, dur))

filtered_trips = []
for (ramp, fset), lst in trip_by_set.items():
    # Keep only the minimum-duration permutation for this set
    best = min(lst, key=lambda x: x[1])
    filtered_trips.append((ramp, best[0], best[1]))

boat_trips = filtered_trips
n_boat_trips = len(boat_trips)
print(f"Enumerated {n_boat_trips} feasible boat trips", file=sys.stderr)

# ---------------------------------------------------------------------------
# MILP Model
# ---------------------------------------------------------------------------
model = Model("flood_relief_routing")
model.setMinimize()
model.setRealGap(0.0005)

# Time limit
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit:
    try:
        time_limit = min(time_limit, float(env_limit))
    except:
        pass
model.setTimeLimit(time_limit)

# --- Truck variables ---
# x[i,j] = 1 if truck goes from i to j
x = {}
for i in nodes:
    for j in nodes:
        if i == j:
            continue
        if (i, j) in road_time:
            x[(i, j)] = model.addVar(name=f"x_{i}_{j}", vtype="B", obj=0.0)

# y[s] = 1 if staging point s is visited (s != depot)
y = {}
for s in nodes:
    if s != DEPOT:
        y[s] = model.addVar(name=f"y_{s}", vtype="B", obj=0.0)

# MTZ position variables for subtour elimination
pos = {}
for s in nodes:
    if s != DEPOT:
        pos[s] = model.addVar(name=f"pos_{s}", vtype="C", lb=0.0, ub=float(n_nodes))

# Arrival time at each node
A = {}
for s in nodes:
    A[s] = model.addVar(name=f"A_{s}", vtype="C", lb=0.0, ub=10000.0)

# --- Shelter service variables ---
# Dry shelters: z[h, s] = 1 if dry shelter h served by truck at staging s
z = {}
for h in shelter_ids:
    if shelters[h]["area"] == "dry":
        s = shelters[h]["dry_node"]
        if s in staging:
            z[(h, s)] = model.addVar(name=f"z_{h}_{s}", vtype="B", obj=0.0)

# Drone: d[h, s] = 1 if shelter h served by drone from launch s
d = {}
for (h, s) in drone_opt_set:
    d[(h, s)] = model.addVar(name=f"d_{h}_{s}", vtype="B", obj=0.0)

# Boat: b[h, k] = 1 if shelter h served by boat trip k
b = {}
for h in flooded_ids:
    for k in range(n_boat_trips):
        ramp, perm, dur = boat_trips[k]
        if h in perm:
            b[(h, k)] = model.addVar(name=f"b_{h}_{k}", vtype="B", obj=0.0)

# --- Completion time and lateness ---
T = model.addVar(name="T", vtype="C", lb=0.0, ub=10000.0, obj=1.0)
lat = {}
for h in shelter_ids:
    lat[h] = model.addVar(name=f"lat_{h}", vtype="C", lb=0.0, ub=10000.0)

# Objective: T + LATE_PEN * sum(w * lat)
obj_terms = [T]
for h in shelter_ids:
    w = pweights[shelters[h]["priority"]]
    obj_terms.append(LATE_PEN * w * lat[h])
model.setObjective(quicksum(obj_terms), "minimize")

# ---------------------------------------------------------------------------
# Constraints
# ---------------------------------------------------------------------------

# 1. Truck flow conservation
for s in nodes:
    if s == DEPOT:
        # Outflow = 1
        model.addCons(
            quicksum(x[(s, j)] for j in nodes if (s, j) in x) == 1,
            name=f"flow_out_{s}"
        )
        # Inflow = 1
        model.addCons(
            quicksum(x[(i, s)] for i in nodes if (i, s) in x) == 1,
            name=f"flow_in_{s}"
        )
    else:
        # Flow conservation
        model.addCons(
            quicksum(x[(i, s)] for i in nodes if (i, s) in x) == y[s],
            name=f"flow_in_{s}"
        )
        model.addCons(
            quicksum(x[(s, j)] for j in nodes if (s, j) in x) == y[s],
            name=f"flow_out_{s}"
        )

# 2. MTZ subtour elimination
M = n_nodes
for i in nodes:
    for j in nodes:
        if i == j or (i, j) not in x:
            continue
        if i == DEPOT or j == DEPOT:
            continue
        # pos[j] >= pos[i] + 1 - M*(1 - x[i,j])
        model.addCons(
            pos[j] >= pos[i] + 1 - M * (1 - x[(i, j)]),
            name=f"mtz_{i}_{j}"
        )
# pos bounds
for s in nodes:
    if s != DEPOT:
        model.chgVarLb(pos[s], 1.0)

# 3. Arrival time constraints
BIG_T = 5000.0
for i in nodes:
    for j in nodes:
        if i == j or (i, j) not in x:
            continue
        # A[j] >= A[i] + stop_time[i] + travel[i,j] - BIG_T*(1 - x[i,j])
        # stop_time[i] is complex; we'll handle via node stop time variable
        # For now, use a simplified approach: define stop_time[i] as a variable
        pass

# Let's define stop time variables
stop_time = {}
for s in nodes:
    stop_time[s] = model.addVar(name=f"stop_{s}", vtype="C", lb=0.0, ub=1000.0)

# Truck stop time composition
for s in nodes:
    base = TRUCK_FIXED + staging[s]["handling"]
    # Direct truck service for dry shelters
    direct_svc = 0.0
    for h in shelter_ids:
        if shelters[h]["area"] == "dry" and shelters[h]["dry_node"] == s:
            if (h, s) in z:
                direct_svc += TRUCK_SVC_PER_KG * shelters[h]["demand"] * z[(h, s)]

    # Drone max duration at s
    drone_durs = []
    for (h, ln) in drone_opt_set:
        if ln == s and (h, ln) in d:
            flight = drone_flight[(h, ln)]
            risk = drone_risk[(h, ln)]
            dur = DRONE_SETUP + flight * max_drone_mult + RISK_PEN * risk
            drone_durs.append(dur * d[(h, ln)])

    # Boat max duration at s
    boat_durs = []
    for k in range(n_boat_trips):
        ramp, perm, dur_base = boat_trips[k]
        if ramp == s:
            dur = dur_base * max_boat_mult
            boat_durs.append(dur * quicksum(b[(h, k)] for h in perm))

    # stop_time[s] >= base + direct_svc
    # stop_time[s] >= max drone dur
    # stop_time[s] >= max boat dur
    # Use auxiliary variables for max
    if drone_durs:
        max_drone = model.addVar(name=f"maxdrone_{s}", vtype="C", lb=0.0, ub=1000.0)
        for expr in drone_durs:
            model.addCons(max_drone >= expr, name=f"maxdrone_{s}_c")
        model.addCons(stop_time[s] >= base + direct_svc + max_drone, name=f"stop_{s}_drone")
    else:
        model.addCons(stop_time[s] >= base + direct_svc, name=f"stop_{s}_base")

    if boat_durs:
        max_boat = model.addVar(name=f"maxboat_{s}", vtype="C", lb=0.0, ub=1000.0)
        for expr in boat_durs:
            model.addCons(max_boat >= expr, name=f"maxboat_{s}_c")
        if drone_durs:
            model.addCons(stop_time[s] >= base + direct_svc + max_boat, name=f"stop_{s}_boat")
        else:
            model.addCons(stop_time[s] >= base + direct_svc + max_boat, name=f"stop_{s}_boat")

# Now arrival time constraints
for i in nodes:
    for j in nodes:
        if i == j or (i, j) not in x:
            continue
        model.addCons(
            A[j] >= A[i] + stop_time[i] + road_time[(i, j)] - BIG_T * (1 - x[(i, j)]),
            name=f"arr_{i}_{j}"
        )

# Completion time = arrival back at depot
model.addCons(T >= A[DEPOT], name="T_def")

# 4. Shelter coverage: each shelter served exactly once
for h in shelter_ids:
    if shelters[h]["area"] == "dry":
        s = shelters[h]["dry_node"]
        if (h, s) in z:
            model.addCons(z[(h, s)] == 1, name=f"cov_{h}")
    else:
        # Flooded: drone or boat
        terms = []
        for (hh, ss) in drone_opt_set:
            if hh == h and (hh, ss) in d:
                terms.append(d[(hh, ss)])
        for k in range(n_boat_trips):
            if (h, k) in b:
                terms.append(b[(h, k)])
        if terms:
            model.addCons(quicksum(terms) == 1, name=f"cov_{h}")
        else:
            # No feasible option - force infeasible
            model.addCons(0 == 1, name=f"cov_infeasible_{h}")

# 5. Drone launch only at visited nodes
for (h, s) in drone_opt_set:
    if (h, s) in d and s in y:
        model.addCons(d[(h, s)] <= y[s], name=f"drone_visit_{h}_{s}")

# 6. Boat launch only at visited ramps
for k in range(n_boat_trips):
    ramp, perm, dur = boat_trips[k]
    if ramp in y:
        for h in perm:
            if (h, k) in b:
                model.addCons(b[(h, k)] <= y[ramp], name=f"boat_visit_{h}_{k}")

# 7. Boat trip all-or-nothing: if any shelter in trip k is served, all are
for k in range(n_boat_trips):
    ramp, perm, dur = boat_trips[k]
    if len(perm) > 1:
        for h in perm:
            if (h, k) in b:
                for h2 in perm:
                    if h2 != h and (h2, k) in b:
                        model.addCons(b[(h, k)] == b[(h2, k)], name=f"boat_all_{k}_{h}_{h2}")

# 8. Shelter completion time and lateness
# For dry shelters: C_h = A[s] + stop_time[s] (approximation: served during stop)
# For drone: C_h = A[s] + drone_duration
# For boat: C_h = A[ramp] + boat_duration
C_h = {}
for h in shelter_ids:
    C_h[h] = model.addVar(name=f"C_{h}", vtype="C", lb=0.0, ub=10000.0)

    if shelters[h]["area"] == "dry":
        s = shelters[h]["dry_node"]
        if (h, s) in z:
            model.addCons(C_h[h] >= A[s] + stop_time[s], name=f"C_{h}_def")
            model.addCons(C_h[h] <= A[s] + stop_time[s] + BIG_T * (1 - z[(h, s)]) + BIG_T, name=f"C_{h}_ub")
    else:
        # Drone
        for (hh, ss) in drone_opt_set:
            if hh == h and (hh, ss) in d:
                flight = drone_flight[(hh, ss)]
                risk = drone_risk[(hh, ss)]
                dur = DRONE_SETUP + flight * max_drone_mult + RISK_PEN * risk
                model.addCons(
                    C_h[h] >= A[ss] + dur - BIG_T * (1 - d[(hh, ss)]),
                    name=f"C_{h}_drone_{ss}"
                )
        # Boat
        for k in range(n_boat_trips):
            ramp, perm, dur_base = boat_trips[k]
            if h in perm and (h, k) in b:
                dur = dur_base * max_boat_mult
                model.addCons(
                    C_h[h] >= A[ramp] + dur - BIG_T * (1 - b[(h, k)]),
                    name=f"C_{h}_boat_{k}"
                )

    # Lateness
    model.addCons(lat[h] >= C_h[h] - shelters[h]["deadline"], name=f"lat_{h}_def")

# ---------------------------------------------------------------------------
# Solve
# ---------------------------------------------------------------------------
print("Solving...", file=sys.stderr)
t0 = time.time()
model.optimize()
solve_time = time.time() - t0

status = model.getStatus()
print(f"Solver status: {status}", file=sys.stderr)
print(f"Solve time: {solve_time:.2f}s", file=sys.stderr)

if model.getNsolns() == 0:
    print("No solution found!", file=sys.stderr)
    # Write empty solution
    with open(SUB_DIR / "solution.csv", "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["row_type", "sequence", "node_id", "trip_id", "mode", "shelter_id", "launch_node"])
    sys.exit(1)

obj = model.getObjval()
print(f"Objective: {obj:.4f}", file=sys.stderr)

# ---------------------------------------------------------------------------
# Extract solution
# ---------------------------------------------------------------------------
# Truck route
route = []
cur = DEPOT
route.append(cur)
for _ in range(n_nodes + 5):  # safety
    next_node = None
    for j in nodes:
        if (cur, j) in x and model.getVal(x[(cur, j)]) > 0.5:
            next_node = j
            break
    if next_node is None:
        break
    route.append(next_node)
    if next_node == DEPOT:
        break
    cur = next_node

print(f"Truck route: {route}", file=sys.stderr)

# Determine which dry shelters are served at each node
dry_served = {}  # h -> s
for h in shelter_ids:
    if shelters[h]["area"] == "dry":
        s = shelters[h]["dry_node"]
        if (h, s) in z and model.getVal(z[(h, s)]) > 0.5:
            dry_served[h] = s

# Drone assignments
drone_assign = {}  # h -> (launch, flight, risk)
for (h, s) in drone_opt_set:
    if (h, s) in d and model.getVal(d[(h, s)]) > 0.5:
        drone_assign[h] = (s, drone_flight[(h, s)], drone_risk[(h, s)])

# Boat assignments
boat_assign = {}  # h -> (trip_k, ramp, perm, dur_base)
for h in flooded_ids:
    for k in range(n_boat_trips):
        if (h, k) in b and model.getVal(b[(h, k)]) > 0.5:
            ramp, perm, dur_base = boat_trips[k]
            boat_assign[h] = (k, ramp, perm, dur_base)
            break

# Verify all shelters covered
uncovered = []
for h in shelter_ids:
    if h in dry_served:
        continue
    if h in drone_assign:
        continue
    if h in boat_assign:
        continue
    uncovered.append(h)
if uncovered:
    print(f"WARNING: Uncovered shelters: {uncovered}", file=sys.stderr)

# ---------------------------------------------------------------------------
# Write solution.csv
# ---------------------------------------------------------------------------
rows = []
# Truck stops
for seq, node in enumerate(route):
    rows.append(["truck_stop", seq, node, "", "", "", ""])

# Delivery rows
# Dry shelters by truck
for h, s in dry_served.items():
    rows.append(["delivery", "", s, "", "truck", h, s])

# Drone deliveries
drone_trip_counter = 0
for h, (launch, flight, risk) in drone_assign.items():
    drone_trip_counter += 1
    trip_id = f"DR{drone_trip_counter:03d}"
    rows.append(["delivery", "", "", trip_id, "drone", h, launch])

# Boat deliveries
boat_trip_counter = 0
# Group by trip
trips_used = {}
for h, (k, ramp, perm, dur_base) in boat_assign.items():
    if k not in trips_used:
        trips_used[k] = {"ramp": ramp, "perm": perm, "dur": dur_base, "shelters": []}
    trips_used[k]["shelters"].append(h)

for k, info in trips_used.items():
    boat_trip_counter += 1
    trip_id = f"BT{boat_trip_counter:03d}"
    ramp = info["ramp"]
    perm = info["perm"]
    for seq, h in enumerate(perm):
        rows.append(["delivery", seq, "", trip_id, "boat", h, ramp])

# Write CSV
with open(SUB_DIR / "solution.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["row_type", "sequence", "node_id", "trip_id", "mode", "shelter_id", "launch_node"])
    for r in rows:
        writer.writerow(r)

print(f"Solution written to {SUB_DIR / 'solution.csv'}", file=sys.stderr)
print(f"Total rows: {len(rows)}", file=sys.stderr)

# Also write model.md
model_md = SUB_DIR / "model.md"
with open(model_md, "w") as f:
    f.write("# Flood Relief Multimodal Routing - Mathematical Model\n\n")
    f.write("## Decision Variables\n")
    f.write("- x[i,j]: truck travels i->j\n")
    f.write("- y[s]: staging point s visited\n")
    f.write("- z[h,s]: dry shelter h served by truck at s\n")
    f.write("- d[h,s]: drone trip for h from s\n")
    f.write("- b[h,k]: boat trip k serves shelter h\n")
    f.write("- A[s]: arrival time at s\n")
    f.write("- T: completion time\n")
    f.write("- lat[h]: lateness of shelter h\n\n")
    f.write("## Objective\n")
    f.write("min T + 1.35 * sum_h w_p(h) * lat_h\n\n")
    f.write("## Constraints\n")
    f.write("1. Truck flow conservation + MTZ subtour elimination\n")
    f.write("2. Each shelter served exactly once\n")
    f.write("3. Dry shelters only by truck at their dry node\n")
    f.write("4. Drone: feasible options, endurance, launch at visited node\n")
